function parseMonths(str){
  const set = new Set();
  String(str).split(",").forEach(r => {
    const [a,b] = r.split("-").map(Number); if(!a) return;
    const end = b || a; let m = a;
    for(let i=0;i<12;i++){ set.add(m); if(m===end) break; m = m%12+1; }
  });
  return set;
}
function haversine(a,b){
  const R=6371, t=Math.PI/180, dLa=(b.lat-a.lat)*t, dLo=(b.lon-a.lon)*t;
  const h=Math.sin(dLa/2)**2+Math.cos(a.lat*t)*Math.cos(b.lat*t)*Math.sin(dLo/2)**2;
  return 2*R*Math.asin(Math.sqrt(h));
}
