$("state").onchange = e => { F.state = e.target.value; F.preset=""; syncControls(); renderAll(); if(F.state) zoomToState(F.state); };
$("status").onchange = e => { F.status = e.target.value; renderAll(); };
$("base").onchange = e => { F.base = e.target.value; F.preset=""; syncControls(); renderAll(); };
$("km").oninput = e => { F.km = +e.target.value; F.preset=""; updateKm(); renderAll(); };
function updateKm(){ $("kmOut").textContent = F.km >= 3000 ? "any" : `${F.km} km`; }
$("reset").onclick = () => { Object.assign(F,{q:"",month:0,state:"",status:"all",km:3000,preset:"",trip:""}); F.cats.clear(); $("q").value=""; syncControls(); renderAll(); fitAll(); };
function syncControls(){
  $("month").value = F.month; $("state").value = F.state; $("status").value = F.status; $("base").value = F.base; $("km").value = F.km; updateKm();
  catsEl.querySelectorAll(".chip").forEach(b => b.setAttribute("aria-pressed", F.cats.has(b.dataset.cat)));
  document.querySelectorAll("#presets .chip").forEach(b => b.setAttribute("aria-pressed", F.preset === b.dataset.preset));
}
function applyPreset(p){
  const on = F.preset !== p;
  Object.assign(F,{month:0,state:"",km:3000,preset:""}); F.cats.clear();
  if(on){
    F.preset = p;
    if(p==="aru"){ F.state = "Arunachal Pradesh"; F.month = 12; }
    if(p==="now"){ F.month = new Date().getMonth()+1; }
    if(p==="weekend"){ F.base = "rpr"; F.km = 300; }
    if(p==="odisha"){ F.state = "Odisha"; F.base = "bbs"; }
  }
  syncControls(); renderAll();
  if(F.state) zoomToState(F.state); else if(p==="weekend" && on) zoomToPoint(BASES.rpr, 5); else fitAll();
}
document.querySelectorAll("#presets .chip").forEach(b => b.onclick = () => applyPreset(b.dataset.preset));
function statusOf(p){ return store.visited[p.id] ? "v" : store.wish[p.id] ? "w" : "n"; }
function filtered(){
  return PLACES.filter(p => {
    if(F.cats.size && !p.cats.some(c => F.cats.has(c))) return false;
    if(F.month && !p.months.has(F.month)) return false;
    if(F.state && p.state !== F.state) return false;
    if(F.km < 3000 && p.dist[F.base] > F.km) return false;
    const s = statusOf(p);
    if(F.status==="v" && s!=="v") return false;
    if(F.status==="w" && s!=="w") return false;
    if(F.status==="n" && s==="v") return false;
    if(F.status==="t" && !tripsWith(p.id).length) return false;
    if(F.trip){ const t = tripById(F.trip); if(!t || !t.places.includes(p.id)) return false; }
    if(F.q){ const hay = (p.name+" "+p.state+" "+p.about+" "+p.info+" "+p.cats.map(c=>CATS[c]).join(" ")).toLowerCase(); if(!hay.includes(F.q)) return false; }
    return true;
  }).sort((a,b) => { if(F.trip){ const t = tripById(F.trip); if(t) return t.places.indexOf(a.id) - t.places.indexOf(b.id); } return a.dist[F.base]-b.dist[F.base]; });
}

// ---------- map ----------
const svg = d3.select("#map");
