const SEAS = [["Arabian Sea",15.2,65.8,22],["Bay of Bengal",15.2,88.6,22],["Indian Ocean",3.6,79.5,22],["Laccadive Sea",8.4,74.4,14],["Andaman Sea",11.2,96.2,14]];
const NEIGH = [["PAKISTAN",28.4,67.4],["NEPAL",28.25,83.9],["BHUTAN",27.5,90.45],["BANGLADESH",23.9,90.3],["MYANMAR",21.3,95.5],["SRI LANKA",7.6,80.7],["CHINA",33.6,87.5],["AFGHANISTAN",34.6,65.2]];
const RANGES = [["Himalaya",30.9,79.2,24,15],["Karakoram",35.55,76.4,-18,11],["Western Ghats",13.6,75.35,-78,11],["Eastern Ghats",16.2,80.2,-50,11],["Vindhya Range",23.75,78.4,-6,10],["Satpura Range",21.95,77.5,-4,10],["Aravalli",25.3,73.9,-47,10],["Thar Desert",27.1,71.2,0,12],["Deccan Plateau",17.6,77.3,0,13],["Indo-Gangetic Plain",26.8,81.2,14,11],["Chota Nagpur",23.35,85.1,0,10],["Naga Hills",25.9,94.7,-62,9]];
