const zoom = d3.zoom().scaleExtent([1, 40]).on("zoom", e => {
  K = e.transform.k; root.attr("transform", e.transform); scaleMarks();
});
svg.call(zoom).on("dblclick.zoom", null);

let lastW = 0;
function layout(){
  const r = $("stage").getBoundingClientRect(); W = Math.max(300, r.width); H = Math.max(300, r.height);
  if(!lastW && W < 600){ $("reel").classList.add("min"); $("reelToggle").textContent = "Show"; $("reelToggle").setAttribute("aria-expanded", false); }
  if(lastW && Math.abs(W - lastW) / lastW > 0.15) svg.call(zoom.transform, d3.zoomIdentity);
  lastW = W;
  const reelH = reelSpace();
  svg.attr("viewBox", `0 0 ${W} ${H}`);
  projection.fitExtent([[24,20],[W-64,H-reelH]], {type:"FeatureCollection", features:states});
  path = d3.geoPath(projection);
  const [x0,y0] = projection([RELIEF.lon0, RELIEF.lat1]), [x1,y1] = projection([RELIEF.lon1, RELIEF.lat0]);
  L.relief.selectAll("image").data([0]).join("image").attr("class","relief").attr("href", RELIEF.href)
    .attr("x",x0).attr("y",y0).attr("width",x1-x0).attr("height",y1-y0).attr("preserveAspectRatio","none");
  zoom.translateExtent([[x0,y0],[x1,y1]]);
  L.veil.selectAll("path").data([0]).join("path").attr("class","veil").attr("fill-rule","evenodd")
    .attr("d", `M-20000,-20000H20000V20000H-20000Z` + path(indiaLand));
  L.states.selectAll("path").data(states).join("path").attr("class","state").attr("d",path)
    .on("click", (e,d) => { if(addMode) return; F.state = F.state === d.properties.ST_NM ? "" : d.properties.ST_NM; F.preset=""; syncControls(); renderAll(); if(F.state) zoomToState(F.state); })
    .on("mousemove", (e,d) => { if(!addMode) showTip(e, `<b>${esc(d.properties.ST_NM)}</b><span>${stateCount(d.properties.ST_NM)}</span>`, true); })
    .on("mouseleave", hideTip);
  L.rivers.selectAll("path").data(RIVERS.features).join("path").attr("class","river").attr("d",path)
    .attr("id",(d,i)=>"rv"+i).attr("stroke-width", d => d.properties.r <= 3 ? 1.6 : d.properties.r <= 5 ? 1.1 : .7);
  L.lines.selectAll("*").remove();
  L.lines.append("path").attr("class","borders").attr("d", path(mesh));
  L.lines.append("path").attr("class","glow").attr("d", path(outline));
  L.lines.append("path").attr("class","outline").attr("d", path(outline));
  L.lines.append("path").attr("class","sel-state");
  // labels
  L.labels.selectAll("*").remove();
  SEAS.forEach(([t,la,lo,fs]) => L.labels.append("text").attr("class","sea-l").attr("data-fs",fs).attr("text-anchor","middle").attr("transform",`translate(${projection([lo,la])})`).text(t));
  NEIGH.forEach(([t,la,lo]) => L.labels.append("text").attr("class","neigh-l").attr("data-fs",9.5).attr("text-anchor","middle").attr("transform",`translate(${projection([lo,la])})`).text(t));
  RANGES.forEach(([t,la,lo,rot,fs]) => L.labels.append("text").attr("class","range-l").attr("data-fs",fs).attr("data-rot",rot).attr("text-anchor","middle").attr("data-x",projection([lo,la])[0]).attr("data-y",projection([lo,la])[1]).text(t));
  const longest = new Map();
  RIVERS.features.forEach((f,i) => { if(!RIVER_LABELS.has(f.properties.n)) return; const len = d3.geoLength(f); if(!longest.has(f.properties.n) || longest.get(f.properties.n).len < len) longest.set(f.properties.n,{i,len}); });
  longest.forEach((v,n) => L.labels.append("text").attr("class","rlabel").attr("data-fs",10).attr("dy",-3).append("textPath").attr("href","#rv"+v.i).attr("startOffset","50%").attr("text-anchor","middle").text(n));
  L.peaks.selectAll("g").data(PEAKS).join(en => { const g = en.append("g").attr("class","peak"); g.append("path"); g.append("text"); return g; })
    .attr("transform", d => `translate(${projection([d[2],d[1]])})`);
  renderAll();
}
function reelSpace(){ return $("reel").classList.contains("min") ? 64 : (W < 600 ? 175 : 215); }
function stateCount(name){
  const all = BUILTIN.filter(p=>p.state===name), v = all.filter(p=>store.visited[p.id]).length;
  return `${all.length} places · ${v} visited`;
}
function scaleMarks(){
  const s = 1/K;
  const base = Math.max(1.6, (W < 600 ? 4.4 : 6) / Math.pow(K, .72));
  L.pins.selectAll(".core").attr("r", base);
  L.pins.selectAll(".ring").attr("r", base + 3.4/Math.pow(K,.72));
  L.pins.selectAll(".pulse").attr("r", base);
  L.pins.selectAll(".cust").attr("d", d3.symbol(d3.symbolDiamond, (base*2.4)**2)());
  L.labels.selectAll("text").each(function(){
    const t = d3.select(this), fs = +t.attr("data-fs");
    t.style("font-size", `${fs*s*(W < 600 ? .68 : 1)*(t.classed("range-l")||t.classed("sea-l") ? Math.min(1.35, Math.pow(K,.18)) : 1)}px`).style("stroke-width", `${3*s}px`);
    if(t.classed("range-l")) t.attr("transform", `translate(${t.attr("data-x")},${t.attr("data-y")}) rotate(${t.attr("data-rot")})`);
  });
  L.labels.selectAll(".rlabel").attr("dy", -3*s).attr("opacity", K > 1.6 ? 1 : 0);
  L.labels.selectAll(".range-l").attr("opacity", K > 7 ? 0 : .8);
  L.labels.selectAll(".sea-l,.neigh-l").attr("opacity", K > 6 ? 0 : 1);
  L.peaks.selectAll("path").attr("d", `M0,${-5*s}L${4.5*s},${3*s}L${-4.5*s},${3*s}Z`);
  L.peaks.selectAll("text").attr("x", 6*s).attr("y", 3*s).style("font-size", `${9.5*s}px`).style("stroke-width", `${2.5*s}px`).text(d=>d[0]);
  L.peaks.attr("opacity", K > 1.4 ? 1 : 0);
  L.homes.selectAll("path").attr("d", `M0,${-7*s}L${6*s},${-1.5*s}V${5*s}H${-6*s}V${-1.5*s}Z`);
  L.homes.selectAll("text").attr("x", 9*s).attr("y", 4*s).style("font-size", `${11.5*s}px`).style("stroke-width", `${3*s}px`).text(d=>d.name);
}
function renderMap(list){
  const counts = d3.rollup(BUILTIN, v => v.length, p => p.state);
  const vis = d3.rollup(BUILTIN.filter(p=>store.visited[p.id]), v => v.length, p => p.state);
  L.tint.selectAll("path").data(states).join("path").attr("class","tint").attr("d",path)
    .attr("fill-opacity", d => { const n = vis.get(d.properties.ST_NM)||0; return n ? .14 + .36*(n/(counts.get(d.properties.ST_NM)||1)) : 0; });
  const sel = states.find(s => s.properties.ST_NM === F.state);
  L.lines.select(".sel-state").attr("d", sel ? path(sel) : null);
  L.homes.selectAll("g").data([BASES[F.base]], d => d.key).join(en => { const g = en.append("g").attr("class","home"); g.append("path"); g.append("text"); return g; })
    .attr("transform", d => `translate(${projection([d.lon,d.lat])})`);
  const rt = F.trip ? tripById(F.trip) : null, rps = rt ? tripPlaces(rt) : [];
  L.route.selectAll("path").data(rps.length > 1 ? [0] : []).join("path").attr("class","route").attr("stroke", rt ? rt.color : null)
    .attr("d", () => "M" + rps.map(p => projection([p.lon,p.lat]).join(",")).join("L"));
  L.pins.selectAll("g.pin").data(list, d => d.id).join(enter => {
    const g = enter.append("g");
    g.append("circle").attr("class","pulse");
    g.append("circle").attr("class","ring");
    g.each(function(d){ d.custom ? d3.select(this).append("path").attr("class","cust core-like") : d3.select(this).append("circle").attr("class","core"); });
    g.on("click", (e,d) => { e.stopPropagation(); select(d.id, false); })
     .on("mousemove", (e,d) => showTip(e, `${thumbHTML(d)}<div class="tx"><b>${esc(d.name)}</b><span>${esc(d.state)} · ${Math.round(d.dist[F.base]).toLocaleString("en-IN")} km from ${BASES[F.base].name}</span></div>`))
     .on("mouseleave", hideTip);
    return g;
  }).attr("class", d => `pin ${statusOf(d)} ${d.id===selectedId?"sel":""}`)
    .attr("transform", d => `translate(${projection([d.lon,d.lat])})`)
    .each(function(d){ d3.select(this).select(".core,.cust").attr("fill", catColor(d.cats[0])).attr("stroke","#fff"); });
  L.pins.selectAll("g.pin").sort((a,b) => ((a.id===selectedId) - (b.id===selectedId)) || (b.lat - a.lat));
  scaleMarks();
}
const tip = $("tip");
function showTip(e, html, isState){
  const r = $("stage").getBoundingClientRect();
  tip.className = "tip" + (isState ? " state-tip" : ""); tip.innerHTML = html; tip.hidden = false;
  let x = e.clientX - r.left + 16, y = e.clientY - r.top - tip.offsetHeight - 12;
  if(x + tip.offsetWidth > r.width - 8) x = e.clientX - r.left - tip.offsetWidth - 16;
  if(y < 8) y = e.clientY - r.top + 16;
  tip.style.left = x+"px"; tip.style.top = y+"px";
}
function hideTip(){ tip.hidden = true; }
function viewBox(){
  const open = !$("detail").hidden && W > 900;
  const availW = open ? W - 480 : W - 60;
  const reelH = reelSpace();
  return {cx: open ? availW/2 : W/2 - 20, cy:(H - reelH)/2, w:availW, h:H - reelH};
}
function fitAll(){ svg.transition().duration(650).call(zoom.transform, d3.zoomIdentity); }
function zoomToState(name){
  const s = states.find(x => x.properties.ST_NM === name); if(!s) return;
  const [[x0,y0],[x1,y1]] = path.bounds(s), v = viewBox();
  const k = Math.min(30, 0.8 / Math.max((x1-x0)/v.w, (y1-y0)/v.h));
  svg.transition().duration(750).call(zoom.transform, d3.zoomIdentity.translate(v.cx,v.cy).scale(Math.max(1,k)).translate(-(x0+x1)/2, -(y0+y1)/2));
}
function zoomToPoint(p, k){
  const [x,y] = projection([p.lon,p.lat]), v = viewBox();
  svg.transition().duration(750).call(zoom.transform, d3.zoomIdentity.translate(v.cx,v.cy).scale(k || Math.max(K,5)).translate(-x,-y));
}
$("zin").onclick = () => svg.transition().duration(300).call(zoom.scaleBy, 1.6);
$("zout").onclick = () => svg.transition().duration(300).call(zoom.scaleBy, 1/1.6);
$("zfit").onclick = fitAll;
$("theme").onclick = () => {
  const cur = document.documentElement.dataset.theme || (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light");
  document.documentElement.dataset.theme = cur === "dark" ? "light" : "dark";
};
$("reelToggle").onclick = () => { const m = $("reel").classList.toggle("min"); $("reelToggle").textContent = m ? "Show" : "Hide"; $("reelToggle").setAttribute("aria-expanded", !m); };

// ---------- add own place ----------
$("addBtn").onclick = () => { if(!addMode && !canUse("custom")) return; addMode = !addMode; $("addBtn").setAttribute("aria-pressed", addMode); $("hint").hidden = !addMode; svg.classed("adding", addMode); };
svg.on("click", e => {
  if(!addMode) return;
  const t = d3.zoomTransform(svg.node()), [mx,my] = d3.pointer(e, svg.node());
  const [lon,lat] = projection.invert(t.invert([mx,my]));
  const st = states.find(s => d3.geoContains(s, [lon,lat]));
  addMode = false; $("addBtn").setAttribute("aria-pressed","false"); $("hint").hidden = true; svg.classed("adding", false);
  openAddForm(lat, lon, st ? st.properties.ST_NM : "");
});
function openAddForm(lat, lon, state){
  panelMode = "add"; selectedId = null;
  const d = $("detail"); d.hidden = false;
  d.innerHTML = `<div class="plain-head"><h2>Add a place</h2><div class="lbl" style="margin-top:4px">${esc(state || "Outside state boundaries")} · ${lat.toFixed(3)}°N ${lon.toFixed(3)}°E</div><button class="close" aria-label="Close">✕</button></div>
  <div class="dscroll"><div class="dbody"><form class="form" id="addForm">
    <label class="lbl" for="nName">Name</label><input id="nName" required maxlength="80" placeholder="e.g. Hatkeshwar temple">
    <label class="lbl" for="nCat">Type</label><select id="nCat" style="width:auto">${Object.entries(CATS).map(([k,v])=>`<option value="${k}">${v}</option>`).join("")}</select>
    <label class="lbl" for="nAbout">Notes</label><textarea id="nAbout" maxlength="600" placeholder="Why go, who told you, best time…"></textarea>
    <button class="primary" type="submit">Save place</button></form></div></div>`;
  d.querySelector(".close").onclick = closeDetail;
  $("nName").focus();
  $("addForm").onsubmit = ev => {
    ev.preventDefault();
    const c = { id:"u-"+Date.now().toString(36), name:$("nName").value.trim(), cat:$("nCat").value, about:$("nAbout").value.trim(), lat:+lat.toFixed(5), lon:+lon.toFixed(5), state };
    if(!c.name) return;
    store.custom = [...(store.custom||[]), c]; store.wish[c.id] = true;
    rebuildPlaces(); save(); renderAll(); select(c.id, false);
  };
}

// ---------- things to carry ----------
function carryList(p){
  const out = ["Govt photo ID (Aadhaar / office ID) — hotels & permits ask for it", "UPI + some cash in small notes", "Power bank, charger, personal medicines & small first-aid kit"];
  const has = c => p.cats.includes(c), info = (p.info||"").toLowerCase();
  if(/ilp|permit|registration|e-pass|rfid/.test(info)) out.push("Permit / registration printout plus PDF on phone, 2 passport photos");
  if(p.alt >= 2500){
    out.push("Thermal innerwear, fleece or down jacket, woollen cap & gloves");
    out.push("UV sunglasses, SPF 50 sunscreen, lip balm, moisturiser");
    out.push("Water 3–4 L/day, ORS, dry fruits; skip alcohol first 2 days");
  } else if(has("M")) out.push("Light jacket or sweater for evenings, shoes with good grip");
  if(p.alt >= 3000) out.push("AMS plan: climb slowly, rest on arrival; Diamox only after a doctor's advice; oximeter helps");
  if(p.alt >= 4000) out.push("Keep visits short at this height; descend if headache, vomiting or breathlessness grows");
  if(has("B")) out.push("Sunscreen, hat, quick-dry clothes, flip-flops, dry bag for phone");
  if(has("W")) out.push("Earth-tone clothes (no bright colours), binoculars, S25 Ultra 10× lens for telephoto; ID must match safari booking");
  if(has("S")) out.push("Modest clothing (shoulders & knees covered), socks for hot stone floors; phones often not allowed — carry minimal");
  if(has("H")) out.push("Comfortable walking shoes, cap, water; ASI e-ticket on phone");
  if(has("D")) out.push("Scarf / face cover for sand, sunglasses, warm layer for cold desert nights");
  if(has("A")) out.push("Trekking shoes, rain jacket or poncho, headlamp, trekking pole");
  if(has("N") && !has("A")) out.push("Rain jacket and non-slip sandals near falls");
  if(NE.has(p.state) || /leech/.test(info)) out.push("Leech socks & insect repellent (wet months), light rain jacket any time");
  if(has("O") || /atm|network|remote/.test(info)) out.push("Offline Google Maps of the area, extra cash — ATMs and signal can be scarce");
  if(/lwe/.test(info)) out.push("Travel in daylight, keep a local contact informed");
  if(p.state === "Jammu & Kashmir" || p.state === "Ladakh") out.push("Postpaid SIM — prepaid from other states doesn't work here");
  return [...new Set(out)];
}
function autoFlags(p){
  const f = [];
  if(p.alt >= 3000) f.push(`<span class="warn">High altitude (${p.alt.toLocaleString("en-IN")} m)</span> — acute mountain sickness is a real risk.`);
  if(F.month && !p.months.has(F.month)) f.push(`<span class="warn">${MONTH_FULL[F.month-1]} is outside the best season.</span>`);
  return f;
}

// ---------- detail ----------
let photoIdx = 0, seasonOnly = false;
function galleryOf(p, full){
  const mine = shownPhotos(p).map(u => ({ kind:"u", id:u.id, m:u.m, y:u.y, at:u.at }));
  const e = photosOf(p);
  const commons = e ? e.p.map((ph,i) => ({ kind:"c", ...ph, i })) : [];
  const remote = remotePhotosOf(p).map(r => ({ kind:"r", ...r }));
  const all = mine.concat(commons, remote);
  const inS = all.filter(ph => ph.m && p.months.has(ph.m));
  return !full && seasonOnly && inS.length ? inS : all;
}
function photoStyle(p, g, contain){
  if(g.kind === "u") return `background-image:url('${blobSrc(g.id)}');background-size:${contain?"contain":"cover"};background-position:center;background-repeat:no-repeat`;
  if(g.kind === "r") return `background-image:url('${safeImgUrl(g.u)}');background-size:${contain?"contain":"cover"};background-position:center;background-repeat:no-repeat`;
  return stripStyle(p, g.i);
}
function photoCaption(p, g){
  if(g.kind === "u"){
    const b = !g.m ? `<span class="badge you">Your photo</span>` : p.months.has(g.m) ? `<span class="badge in">● Your photo · best season · ${MON[g.m-1]} ${g.y||""}</span>` : `<span class="badge off">Your photo · ${MON[g.m-1]} ${g.y||""}</span>`;
    return `${b}<span class="credit">Added ${fmtD(g.at, true)}</span>`;
  }
  const file = g.kind === "r" ? g.f : g.title;
  return `${photoBadge(g,p)}<span class="credit">© <a href="${esc(commonsFile(file))}" target="_blank" rel="noopener noreferrer">${esc(g.a)}</a>${g.l?" · "+esc(g.l):""} · Wikimedia Commons</span>`;
}
function select(id, pan){
  const changed = selectedId !== id;
  panelMode = "place"; selectedId = id; const p = PLACES.find(x => x.id === id); if(!p) return;
  if(changed){ photoIdx = 0; seasonOnly = false; armPhoto = null; }
  renderAll(); renderDetail(p);
  if(pan) zoomToPoint(p);
  const li = document.querySelector(`.item[data-id="${CSS.escape(id)}"]`); if(li) li.scrollIntoView({block:"nearest"});
}
function closeDetail(){ $("detail").hidden = true; selectedId = null; panelMode = "none"; renderAll(); }
function renderDetail(p){
  if(panelMode !== "place" || selectedId !== p.id) return;
  const d = $("detail"); d.hidden = false;
  const keep = d.querySelector(".dscroll"), top = keep && d.dataset.pid === p.id ? keep.scrollTop : 0;
  d.dataset.pid = p.id;
  const s = statusOf(p), now = new Date().getMonth()+1, km = k => Math.round(p.dist[k]);
  const gal = galleryOf(p), all = galleryOf(p, true);
  if(photoIdx >= gal.length) photoIdx = 0;
  const cur = gal[photoIdx];
  const inCount = all.filter(ph => ph.m && p.months.has(ph.m)).length;
  const infoItems = [...autoFlags(p), ...(p.info ? p.info.split(/(?<=\.)\s+/).map(esc) : [])];
  const bestMonths = MON.filter((m,i)=>p.months.has(i+1));
  const peakMonth = MONTH_FULL[[...p.months][0]-1];
  const inTrips = tripsWith(p.id);
  const prem = premiumOK(), canUp = !!assetsNS && prem;
  const upButtons = canUp ? `<div class="upl"><button id="upCam" title="Take a photo" aria-label="Take a photo with camera">${ico("cam")}</button><button id="upGal" title="Upload from gallery" aria-label="Upload photos from gallery">${ico("gal")}</button></div>` : "";
  d.innerHTML = `
  <div class="dscroll">
    <div class="hero ${cur?"":"art"}" id="hero" style="${cur ? photoStyle(p,cur) : `background:linear-gradient(135deg, ${catColor(p.cats[0])}, color-mix(in srgb, ${catColor(p.cats[0])} 45%, #0b1218))`}">
      ${cur ? "" : `<div style="position:absolute;inset:0;display:grid;place-items:center;opacity:.3">${svgIcon(p.cats[0],"#fff").replace("<svg","<svg width=\"38%\" height=\"38%\"")}</div>`}
      ${!cur && canUp ? `<div class="heroadd"><button id="heroCam">${ico("cam")} Camera</button><button id="heroGal">${ico("gal")} Gallery</button></div>` : ""}
      ${gal.length>1 ? `<span class="count">${photoIdx+1} / ${gal.length}</span><button class="nav prev" id="pPrev" aria-label="Previous photo">‹</button><button class="nav next" id="pNext" aria-label="Next photo">›</button>` : ""}
      <button class="close" aria-label="Close">✕</button>
      <div class="shade"><h2>${esc(p.name)}</h2><p>${esc(p.state)}${p.alt!=null ? ` · ${p.alt.toLocaleString("en-IN")} m` : ""} · best ${bestMonths.length===12?"all year":bestMonths[0]+"–"+bestMonths[bestMonths.length-1]}</p></div>
    </div>
    <div class="photometa">${cur ? photoCaption(p,cur) : `<span class="badge na">No photo yet</span><span>${canUp ? "Add your own shot" : "See real photos with the links below"}</span>`}
      ${cur && cur.kind==="u" && canUp ? `<button class="mini del" id="delPhoto">${ico("trash")} ${armPhoto===cur.id ? "Tap again to delete" : "Delete"}</button>` : ""}
      ${uploading ? `<span class="upstatus">${uploading}</span>` : ""}${upButtons}</div>
    ${all.length>1 ? `<div class="strip">${gal.map((ph,j)=>`<button data-j="${j}" aria-current="${j===photoIdx}" aria-label="Photo ${j+1}" style="${photoStyle(p,ph)}">${ph.m && p.months.has(ph.m) ? "<i></i>" : ""}</button>`).join("")}</div>` : ""}
    ${inCount && inCount < all.length ? `<div class="photometa"><label><input type="checkbox" id="seasonOnly" ${seasonOnly?"checked":""}> Best-season photos only (${inCount})</label></div>` : ""}
    <input type="file" id="fCam" accept="image/*" capture="environment" hidden>
    <input type="file" id="fGal" accept="image/jpeg,image/png,image/webp,image/*" multiple hidden>
    <div class="dbody">
      <div class="catrow">${p.cats.map(c=>`<span class="cat" style="background:${catColor(c)}">${CATS[c]}</span>`).join("")}${p.custom?'<span class="cat" style="background:var(--muted)">Added by you</span>':""}</div>
      <div class="actions">
        <button class="act v" id="bV" aria-pressed="${s==="v"}">${s==="v"?"✓ Visited":"Mark visited"}</button>
        <button class="act w" id="bW" aria-pressed="${!!store.wish[p.id]}">${store.wish[p.id]?"★ On wishlist":"☆ Wishlist"}</button>
      </div>
      ${prem ? `<div class="addtrip"><select id="tripSel" aria-label="Add to a trip"><option value="">Add to a trip…</option>${store.trips.map(t=>`<option value="${t.id}" ${t.places.includes(p.id)?"disabled":""}>${esc(t.name)} (${fmtD(t.start)})${t.places.includes(p.id)?" ✓":""}</option>`).join("")}<option value="__new">+ New trip with this place</option></select></div>
      ${inTrips.length ? `<div class="intrip">In trip: ${inTrips.map(t=>`<button data-trip="${t.id}">${esc(t.name)}</button>`).join(", ")}</div>` : ""}` : ""}
      ${store.visited[p.id] ? `<div style="color:var(--visited);font-size:12.5px">Marked visited on ${new Date(store.visited[p.id]).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"})}</div>` : ""}
      ${p.about ? `<div class="sec"><h3>About</h3><p>${esc(p.about)}</p></div>` : ""}
      <div class="facts">
        <div class="fact"><span class="lbl">From ${esc(BASES[F.base].name)}</span><b>${km(F.base).toLocaleString("en-IN")} km</b><em>≈ ${(Math.round(km(F.base)*1.35/10)*10).toLocaleString("en-IN")} km by road · ${esc(BASES[F.base].st)} capital</em></div>
        ${p.gateway ? `<div class="fact"><span class="lbl">Getting there</span><b style="font-size:13px">${esc(p.gateway)}</b></div>` : ""}
        ${p.days ? `<div class="fact"><span class="lbl">Suggested time</span><b>${p.days} day${p.days>1?"s":""}</b><em>on site, excl. travel</em></div>` : ""}
      </div>
      <div class="sec"><h3>Best months</h3><div class="months">${MON.map((m,i)=>`<span class="${p.months.has(i+1)?"on":""} ${i+1===now?"now":""}" title="${MONTH_FULL[i]}">${m[0]}</span>`).join("")}</div></div>
      ${prem ? `${typeof weatherHTML === "function" ? weatherHTML(p) : ""}
      ${infoItems.length ? `<div class="sec info"><h3>Know before you go</h3><ul>${infoItems.map(x=>`<li>${x}</li>`).join("")}</ul></div>` : ""}
      <div class="sec"><h3>Things to carry</h3><ul class="carry">${carryList(p).map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>
      ${voicesHTML(p)}
      <div class="sec"><h3><label for="note">My notes</label></h3><textarea id="note" maxlength="1500" placeholder="Stay booked, contacts, photo spots…">${esc(store.notes[p.id]||"")}</textarea></div>` : lockedCard()}
      <div class="links">
        <a class="ext" href="https://www.google.com/search?tbm=isch&q=${encodeURIComponent(p.q+" "+peakMonth)}" target="_blank" rel="noopener noreferrer">${esc(peakMonth)} photos ↗</a>
        <a class="ext" href="https://commons.wikimedia.org/w/index.php?title=Special:MediaSearch&type=image&search=${encodeURIComponent(p.q)}" target="_blank" rel="noopener noreferrer">More on Commons ↗</a>
        <a class="ext" href="https://www.google.com/maps/search/?api=1&query=${p.lat},${p.lon}" target="_blank" rel="noopener noreferrer">Google Maps ↗</a>
      </div>
      ${p.custom ? `<button class="danger" id="bDel">Remove this place</button>` : ""}
    </div>
  </div>`;
  const sc = d.querySelector(".dscroll"); if(sc) sc.scrollTop = top;
  d.querySelector(".close").onclick = closeDetail;
  const go = step => { photoIdx = (photoIdx + step + gal.length) % gal.length; armPhoto = null; renderDetail(p); };
  if($("pPrev")){ $("pPrev").onclick = ev => { ev.stopPropagation(); go(-1); }; $("pNext").onclick = ev => { ev.stopPropagation(); go(1); }; }
  d.querySelectorAll(".strip button").forEach(b => b.onclick = () => { photoIdx = +b.dataset.j; armPhoto = null; renderDetail(p); });
  if($("seasonOnly")) $("seasonOnly").onchange = ev => { seasonOnly = ev.target.checked; photoIdx = 0; renderDetail(p); };
  if(cur) $("hero").onclick = ev => { if(ev.target.closest("button")) return; openLightbox(p); };
  const pickCam = () => $("fCam").click(), pickGal = () => $("fGal").click();
  [["upCam",pickCam],["upGal",pickGal],["heroCam",pickCam],["heroGal",pickGal]].forEach(([i,f]) => { if($(i)) $(i).onclick = ev => { ev.stopPropagation(); f(); }; });
  $("fCam").onchange = ev => { if(ev.target.files.length) handleFiles(p, ev.target.files); };
  $("fGal").onchange = ev => { if(ev.target.files.length) handleFiles(p, ev.target.files); };
  if($("delPhoto")) $("delPhoto").onclick = () => deleteUserPhoto(p, cur.id);
  if($("tripSel")) $("tripSel").onchange = ev => {
    const v = ev.target.value; if(!v) return;
    if(v === "__new"){
      const st = addDays(todayISO(), 30);
      const t = { id:uid(), name:`${p.name.split(/ [—–(&]| &/)[0]} trip`, start:st, end:addDays(st, Math.max(1,(p.days||2)-1)), notes:"", color:TRIP_COLORS[store.trips.length % TRIP_COLORS.length], places:[p.id] };
      store.trips.push(t); save();
      plan.opened = true; plan.expanded.add(t.id); plan.editing = t.id; plan.color = t.color; plan.month = parseISO(t.start); plan.month.setDate(1);
      openPlanner(); toast("New trip created — set its dates"); return;
    }
    const t = tripById(v); if(t && !t.places.includes(p.id)){ t.places.push(p.id); save(); toast(`Added to ${t.name}`); renderAll(); renderDetail(p); }
  };
  d.querySelectorAll(".intrip button").forEach(b => b.onclick = () => { plan.opened = true; plan.expanded.add(b.dataset.trip); const t = tripById(b.dataset.trip); plan.month = parseISO(t.start); plan.month.setDate(1); openPlanner(); });
  $("bV").onclick = () => { if(store.visited[p.id]) delete store.visited[p.id]; else { store.visited[p.id] = new Date().toISOString().slice(0,10); delete store.wish[p.id]; } save(); renderAll(); renderDetail(p); };
  $("bW").onclick = () => { if(store.wish[p.id]) delete store.wish[p.id]; else store.wish[p.id] = true; save(); renderAll(); renderDetail(p); };
  let nt; if($("note")) $("note").oninput = ev => { clearTimeout(nt); const v = ev.target.value; nt = setTimeout(() => { if(v) store.notes[p.id] = v; else delete store.notes[p.id]; save(); }, 600); };
  if(p.custom){
    let armed = false;
    $("bDel").onclick = ev => {
      if(!armed){ armed = true; ev.target.textContent = "Tap again to remove"; return; }
      store.custom = store.custom.filter(c => c.id !== p.id); delete store.wish[p.id]; delete store.visited[p.id]; delete store.notes[p.id];
      store.trips.forEach(t => t.places = t.places.filter(x => x !== p.id));
      rebuildPlaces(); save(); closeDetail();
    };
  }
}
// lightbox
function openLightbox(p){
  const lb = $("lb"), gal = galleryOf(p);
  const draw = () => {
    const cur = gal[photoIdx];
    lb.innerHTML = `<div><div class="img" style="${photoStyle(p,cur,true)}" role="img" aria-label="${esc(p.name)} photo"></div>
      <div class="cap"><b>${esc(p.name)}</b> · ${photoCaption(p,cur)}</div></div>
      <button class="lx" aria-label="Close">✕</button>${gal.length>1?'<button class="lp" aria-label="Previous">‹</button><button class="ln" aria-label="Next">›</button>':""}`;
    lb.querySelector(".lx").onclick = close;
    if(gal.length>1){ lb.querySelector(".lp").onclick = () => { photoIdx=(photoIdx-1+gal.length)%gal.length; draw(); }; lb.querySelector(".ln").onclick = () => { photoIdx=(photoIdx+1)%gal.length; draw(); }; }
  };
  const close = () => { lb.hidden = true; renderDetail(p); };
  lb.onclick = ev => { if(ev.target === lb) close(); };
  lb.hidden = false; draw(); lb.querySelector(".lx").focus();
}

// ---------- list, reel, stats ----------
function renderList(list){
  $("count").textContent = list.length;
  const tf = $("tripFilter"), ft = F.trip ? tripById(F.trip) : null;
  tf.innerHTML = ft ? `<span class="tripchip">Trip: ${esc(ft.name)}<button id="clearTrip" aria-label="Clear trip filter">✕</button></span>` : "";
  if(ft) $("clearTrip").onclick = () => { F.trip = ""; renderAll(); };
  const ul = $("list");
  if(!list.length){ ul.innerHTML = `<li class="empty">No places match these filters. Try another month or widen the distance.</li>`; return; }
  ul.innerHTML = list.map(p => { const s = statusOf(p); return `<li class="item" role="option" tabindex="0" data-id="${esc(p.id)}" aria-selected="${p.id===selectedId}">
    ${thumbHTML(p)}
    <span><span class="nm">${esc(p.name)}</span><br><span class="st">${esc(p.state)}${s==="v"?' · <span class="tag-v">✓ visited</span>':s==="w"?' · <span class="tag-w">★ wishlist</span>':""}</span></span>
    <span class="km">${Math.round(p.dist[F.base]).toLocaleString("en-IN")} km</span></li>`; }).join("");
}
$("list").addEventListener("click", e => { const li = e.target.closest(".item"); if(li) select(li.dataset.id, true); });
$("list").addEventListener("keydown", e => { if(e.key==="Enter"||e.key===" "){ const li = e.target.closest(".item"); if(li){ e.preventDefault(); select(li.dataset.id, true); } } });
function renderReel(list){
  const m = F.month || (new Date().getMonth()+1);
  let pool = list.filter(p => p.months.has(m) && !p.custom);
  pool.sort((a,b) => (!!store.wish[b.id] - !!store.wish[a.id]) || (!!photosOf(b) - !!photosOf(a)) || a.dist[F.base]-b.dist[F.base]);
  pool = pool.slice(0, 24);
  $("reelTitle").innerHTML = pool.length ? `Best in <em>${MONTH_FULL[m-1]}</em> · nearest to ${BASES[F.base].name}` : `Nothing in season in <em>${MONTH_FULL[m-1]}</em> for these filters`;
  $("reelx").innerHTML = pool.map(p => `<button class="card" data-id="${esc(p.id)}">${thumbHTML(p)}<span class="cx"><b>${esc(p.name)}</b><span>${esc(p.state)} · ${Math.round(p.dist[F.base]).toLocaleString("en-IN")} km</span></span></button>`).join("");
}
$("reelx").addEventListener("click", e => { const c = e.target.closest(".card"); if(c) select(c.dataset.id, true); });
function renderStats(){
  const v = PLACES.filter(p=>store.visited[p.id]).length;
  const w = Object.keys(store.wish).filter(id => PLACES.some(p=>p.id===id) && !store.visited[id]).length;
  const st = new Set(PLACES.filter(p=>store.visited[p.id]).map(p=>p.state)); st.delete("—");
  $("sVisited").textContent = v; $("sWish").textContent = w; $("sStates").textContent = `${st.size}/36`;
  const due = dueReminders(7).length, bd = $("dueBadge");
  bd.hidden = !due; bd.textContent = due; $("tripsBtn").title = due ? `${due} reminder${due>1?"s":""} due within 7 days` : "Trips & reminders";
}
function renderAll(){ const list = filtered(); renderMap(list); renderList(list); renderReel(list); renderStats(); afterRender(); }

// ---------- shared helpers ----------
const uid = () => Math.random().toString(36).slice(2,8) + Date.now().toString(36).slice(-4);
const pad2 = n => String(n).padStart(2,"0");
const iso = d => `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}`;
const parseISO = s => { const [y,m,d] = s.split("-").map(Number); return new Date(y, m-1, d); };
const todayISO = () => iso(new Date());
const addDays = (s,n) => { const d = parseISO(s); d.setDate(d.getDate()+n); return iso(d); };
const dayDiff = (a,b) => Math.round((parseISO(b) - parseISO(a)) / 864e5);
const fmtD = (s, withYear) => parseISO(s).toLocaleDateString("en-IN", withYear ? {day:"numeric",month:"short",year:"numeric"} : {day:"numeric",month:"short"});
const fmtT = t => { if(!t) return ""; const [h,m] = t.split(":").map(Number); return `${((h+11)%12)+1}:${pad2(m)} ${h<12?"am":"pm"}`; };
const TRIP_COLORS = ["#D9731A","#1F8A5B","#3F67B0","#B8437F","#7255BE","#12909D"];
const ICO = {
  cal:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/>',
  cam:'<path d="M4 8h3l2-3h6l2 3h3v11H4z"/><circle cx="12" cy="13" r="3.5"/>',
  gal:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="9" cy="10" r="2"/><path d="M21 17l-5-5-9 8"/>',
  trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13"/>',
  edit:'<path d="M4 20h4L19 9l-4-4L4 16zM14 6l4 4"/>',
  pin:'<path d="M12 21s-7-6.2-7-11a7 7 0 0114 0c0 4.8-7 11-7 11z"/><circle cx="12" cy="10" r="2.5"/>',
  bell:'<path d="M6 16V11a6 6 0 0112 0v5l2 2H4zM10 20a2 2 0 004 0"/>',
  down:'<path d="M12 4v11M7 10l5 5 5-5M5 20h14"/>',
  gcal:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4M9 15h6M12 12v6"/>'
};
const ico = k => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICO[k]}</svg>`;
let toastTimer;
function toast(msg){
  let t = document.querySelector(".toast");
  if(!t){ t = document.createElement("div"); t.className = "toast"; t.setAttribute("role","status"); document.body.appendChild(t); }
  t.textContent = msg; t.hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(() => t.hidden = true, 3200);
}
async function useCap(name){
  let tries = 0;
  while(!(window.claude && window.claude.use) && tries < 20){ await new Promise(r => setTimeout(r,150)); tries++; }
  try { return window.claude && window.claude.use ? await window.claude.use(name) : null; } catch(e){ return null; }
}

// ---------- seed (December trip, editable / removable) ----------
function ensureSeed(){ if(!store.seeded){ store.seeded = true; save(); } }

// ---------- trip helpers ----------
const tripById = id => store.trips.find(t => t.id === id);
const tripPlaces = t => t.places.map(id => PLACES.find(p => p.id === id)).filter(Boolean);
const tripsWith = pid => store.trips.filter(t => t.places.includes(pid));
function tripStatus(t){
  const td = todayISO();
  if(t.end < td) return {cls:"", txt:"Done"};
  if(t.start <= td) return {cls:"now", txt:"On now"};
  const n = dayDiff(td, t.start);
  return {cls: n <= 30 ? "soon" : "", txt: n === 1 ? "Tomorrow" : `In ${n} days`};
}
function sortedTrips(){
  const td = todayISO();
  return [...store.trips].sort((a,b) => ((a.end < td) - (b.end < td)) || a.start.localeCompare(b.start));
}
function dueReminders(days){
  const lim = addDays(todayISO(), days);
  return store.reminders.filter(r => !r.done && r.date <= lim).sort((a,b) => (a.date+a.time).localeCompare(b.date+b.time));
}
function suggestions(t){
  const ps = tripPlaces(t), td = todayISO(), out = [];
  const at = (n, time) => { const d = addDays(t.start, n); return {date: d < td ? td : d, time: time || "09:00"}; };
  out.push({text:"Book train / flights (IRCTC opens 60 days ahead)", ...at(-60)});
  const permit = ps.filter(p => /ilp|permit|registration|e-pass|rfid/i.test(p.info));
  if(permit.length) out.push({text:`Apply for permits: ${permit.map(p=>p.name).join(", ")}`, ...at(-30)});
  const saf = ps.filter(p => p.cats.includes("W"));
  if(saf.length) out.push({text:`Book safari slots: ${saf.map(p=>p.name).join(", ")}`, ...at(-60)});
  out.push({text:"Confirm stays & local cabs", ...at(-7)});
  if(ps.some(p => p.alt >= 2500)) out.push({text:"Pack woollens, check road & weather updates", ...at(-3,"20:00")});
  out.push({text:"Download offline maps, carry ID & cash", ...at(-1,"20:00")});
  const key = s => s.toLowerCase().split(/[^a-z]+/).filter(Boolean).slice(0,2).join(" ");
  const have = new Set(store.reminders.filter(r => r.tripId === t.id).map(r => key(r.text)));
  return t.end < td ? [] : out.filter(s => !have.has(key(s.text)));
}
const gdate = s => s.replace(/-/g,"");
function gcalTrip(t){
  const ps = tripPlaces(t);
  return "https://calendar.google.com/calendar/render?action=TEMPLATE"
    + "&text=" + encodeURIComponent("Trip: " + t.name)
    + "&dates=" + gdate(t.start) + "/" + gdate(addDays(t.end,1))
    + "&details=" + encodeURIComponent(`Places: ${ps.map(p=>p.name).join(", ") || "—"}\n${t.notes || ""}\nPlanned in Bharat Bhramanam`)
    + (ps[0] ? "&location=" + encodeURIComponent(ps[0].name + ", " + ps[0].state) : "");
}
function gcalRem(r){
  const [h,m] = (r.time || "09:00").split(":").map(Number), end = Math.min(h*60 + m + 30, 23*60 + 59);
  const tr = r.tripId ? tripById(r.tripId) : null;
  return "https://calendar.google.com/calendar/render?action=TEMPLATE"
    + "&text=" + encodeURIComponent("Reminder: " + r.text)
    + "&dates=" + gdate(r.date) + "T" + pad2(h) + pad2(m) + "00/" + gdate(r.date) + "T" + pad2(Math.floor(end/60)) + pad2(end%60) + "00"
    + "&ctz=Asia/Kolkata"
    + "&details=" + encodeURIComponent(tr ? `For trip: ${tr.name} (${fmtD(tr.start)} – ${fmtD(tr.end, true)})` : "From Bharat Bhramanam");
}

// ---------- calendar file (.ics inside a .zip) ----------
function icsEsc(s){ return String(s||"").replace(/\\/g,"\\\\").replace(/;/g,"\\;").replace(/,/g,"\\,").replace(/\r?\n/g,"\\n"); }
const utcStamp = d => d.toISOString().replace(/[-:]/g,"").replace(/\.\d+Z$/,"Z");
function icsText(){
  const L2 = ["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//Bharat Bhramanam//EN","CALSCALE:GREGORIAN","METHOD:PUBLISH","X-WR-CALNAME:Bharat Bhramanam trips"];
  const now = utcStamp(new Date());
  store.trips.forEach(t => {
    const ps = tripPlaces(t);
    L2.push("BEGIN:VEVENT", `UID:${t.id}@bharat-bhramanam`, `DTSTAMP:${now}`, `DTSTART;VALUE=DATE:${gdate(t.start)}`, `DTEND;VALUE=DATE:${gdate(addDays(t.end,1))}`,
      `SUMMARY:${icsEsc("Trip: "+t.name)}`, `DESCRIPTION:${icsEsc("Places: "+ps.map(p=>p.name).join(", ")+"\n"+(t.notes||""))}`,
      ...(ps[0] ? [`LOCATION:${icsEsc(ps[0].name+", "+ps[0].state)}`] : []),
      "BEGIN:VALARM","TRIGGER:-P1D","ACTION:DISPLAY",`DESCRIPTION:${icsEsc("Trip tomorrow: "+t.name)}`,"END:VALARM","END:VEVENT");
  });
  store.reminders.filter(r => !r.done).forEach(r => {
    const st = new Date(`${r.date}T${r.time||"09:00"}:00+05:30`), en = new Date(st.getTime() + 30*60000);
    L2.push("BEGIN:VEVENT", `UID:${r.id}@bharat-bhramanam`, `DTSTAMP:${now}`, `DTSTART:${utcStamp(st)}`, `DTEND:${utcStamp(en)}`,
      `SUMMARY:${icsEsc(r.text)}`, "BEGIN:VALARM","TRIGGER:PT0M","ACTION:DISPLAY",`DESCRIPTION:${icsEsc(r.text)}`,"END:VALARM","END:VEVENT");
  });
  L2.push("END:VCALENDAR");
  return L2.join("\r\n");
}
function crc32(bytes){
  let crc = 0xFFFFFFFF;
  for(let i=0;i<bytes.length;i++){ let c = (crc ^ bytes[i]) & 0xFF; for(let k=0;k<8;k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; crc = (crc >>> 8) ^ c; }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}
function zipOne(name, text){
  const enc = new TextEncoder(), nm = enc.encode(name), data = enc.encode(text), crc = crc32(data);
  const d = new Date(), dt = ((d.getHours()<<11)|(d.getMinutes()<<5)|(d.getSeconds()>>1)) & 0xFFFF, dd = (((d.getFullYear()-1980)<<9)|((d.getMonth()+1)<<5)|d.getDate()) & 0xFFFF;
  const loc = new DataView(new ArrayBuffer(30)), cen = new DataView(new ArrayBuffer(46)), end = new DataView(new ArrayBuffer(22));
  [[0,0x04034b50,4],[4,20,2],[6,0,2],[8,0,2],[10,dt,2],[12,dd,2],[14,crc,4],[18,data.length,4],[22,data.length,4],[26,nm.length,2],[28,0,2]]
    .forEach(([o,v,n]) => n===4 ? loc.setUint32(o,v,true) : loc.setUint16(o,v,true));
  [[0,0x02014b50,4],[4,20,2],[6,20,2],[8,0,2],[10,0,2],[12,dt,2],[14,dd,2],[16,crc,4],[20,data.length,4],[24,data.length,4],[28,nm.length,2],[30,0,2],[32,0,2],[34,0,2],[36,0,2],[38,0,4],[42,0,4]]
    .forEach(([o,v,n]) => n===4 ? cen.setUint32(o,v,true) : cen.setUint16(o,v,true));
  const cenOff = 30 + nm.length + data.length;
  [[0,0x06054b50,4],[4,0,2],[6,0,2],[8,1,2],[10,1,2],[12,46+nm.length,4],[16,cenOff,4],[20,0,2]]
    .forEach(([o,v,n]) => n===4 ? end.setUint32(o,v,true) : end.setUint16(o,v,true));
  return new Blob([loc, nm, data, cen, nm, end], {type:"application/zip"});
}
async function downloadCalendar(){
  if(!store.trips.length && !store.reminders.length){ toast("Add a trip or reminder first"); return; }
  saveFile("bharat-bhramanam-trips.ics", new Blob([icsText()], { type:"text/calendar" }));
  toast("Calendar file saved. Open it to add trips & alerts to your calendar");
}

// ---------- planner panel ----------
const plan = { month:null, selDay:null, editing:null, expanded:new Set(), remForm:null, armDel:null, color:TRIP_COLORS[0], opened:false };
let panelMode = "none";
function openPlanner(){
  panelMode = "planner"; selectedId = null;
  if(!plan.opened){
    plan.opened = true;
    const next = sortedTrips()[0];
    plan.month = next && next.end >= todayISO() ? parseISO(next.start) : new Date();
    plan.month.setDate(1);
    if(next) plan.expanded.add(next.id);
  }
  renderAll(); renderPlanner();
}
function remRow(r, showTrip){
  const td = todayISO(), over = !r.done && r.date < td, tr = r.tripId ? tripById(r.tripId) : null;
  return `<div class="rem ${over?"over":""} ${r.done?"done":""}">
    <input type="checkbox" data-act="remdone" data-id="${r.id}" ${r.done?"checked":""} aria-label="Mark done">
    <div><span class="what">${esc(r.text)}</span><span class="when">${over?"Overdue · ":""}${fmtD(r.date, true)} · ${fmtT(r.time)}${showTrip && tr ? " · " + esc(tr.name) : ""}</span></div>
    <div class="acts"><a class="icon-btn" href="${gcalRem(r)}" target="_blank" rel="noopener noreferrer" title="Add to Google Calendar" aria-label="Add to Google Calendar">${ico("gcal")}</a><button class="icon-btn" data-act="remdel" data-id="${r.id}" title="Delete reminder" aria-label="Delete reminder">${ico("trash")}</button></div>
  </div>`;
}
function remForm(ctx){
  const f = plan.remForm, date = f.date || addDays(todayISO(), 1);
  return `<form class="tform" data-form="rem">
    <label>Reminder<input name="text" required maxlength="140" placeholder="e.g. Book Tezpur flight" value="${esc(f.text||"")}"></label>
    <div class="grid2"><label>Date<input type="date" name="date" required value="${date}"></label><label>Time<input type="time" name="time" required value="${f.time||"09:00"}"></label></div>
    ${ctx === "trip" ? `<input type="hidden" name="trip" value="${esc(f.tripId)}">` : `<label>Trip (optional)<select name="trip"><option value="">— None —</option>${store.trips.map(t=>`<option value="${t.id}" ${f.tripId===t.id?"selected":""}>${esc(t.name)}</option>`).join("")}</select></label>`}
    <div class="btnrow"><button class="mini acc" type="submit">Save reminder</button><button class="mini" type="button" data-act="remcancel">Cancel</button></div>
  </form>`;
}
function tripForm(t){
  const v = t || { name:"", start: plan.selDay || addDays(todayISO(), 30), end: addDays(plan.selDay || addDays(todayISO(), 30), 3), notes:"" };
  const color = plan.color;
  return `<form class="tform" data-form="trip" data-id="${t ? t.id : "new"}">
    <label>Trip name<input name="name" required maxlength="80" placeholder="e.g. Odisha coast with family" value="${esc(v.name)}"></label>
    <div class="grid2"><label>Start<input type="date" name="start" required value="${v.start}"></label><label>End<input type="date" name="end" required value="${v.end}"></label></div>
    <label>Colour</label><div class="swatches">${TRIP_COLORS.map(c=>`<button type="button" data-act="swatch" data-c="${c}" aria-pressed="${c===color}" style="background:${c}" aria-label="Colour"></button>`).join("")}</div>
    <label>Notes<textarea name="notes" maxlength="800" placeholder="Who's coming, budget, must-dos…">${esc(v.notes||"")}</textarea></label>
    <div class="btnrow"><button class="mini acc" type="submit">${t ? "Save changes" : "Create trip"}</button><button class="mini" type="button" data-act="tripcancel">Cancel</button></div>
  </form>`;
}
function tripCard(t){
  const st = tripStatus(t), open = plan.expanded.has(t.id), ps = tripPlaces(t), n = dayDiff(t.start, t.end) + 1;
  const rems = store.reminders.filter(r => r.tripId === t.id).sort((a,b) => (a.date+a.time).localeCompare(b.date+b.time));
  const sug = open ? suggestions(t) : [];
  const avail = PLACES.filter(p => !t.places.includes(p.id)).sort((a,b) => a.name.localeCompare(b.name));
  let body = "";
  if(open){
    body = plan.editing === t.id ? `<div class="tbody">${tripForm(t)}</div>` : `<div class="tbody">
      <div class="tplaces">${ps.map((p,i)=>`<div class="tpc" data-act="openplace" data-id="${p.id}" role="button" tabindex="0" aria-label="Open ${esc(p.name)}">${thumbHTML(p)}<span class="tnum">${i+1}</span><button class="trm" data-act="rmplace" data-trip="${t.id}" data-id="${p.id}" aria-label="Remove ${esc(p.name)}">×</button><span class="tpx"><b>${esc(p.name)}</b><span>${esc(p.state)}</span></span></div>`).join("") || `<span class="muted">No places yet — add one below or from any place on the map.</span>`}</div>
      <select data-addplace="${t.id}" aria-label="Add a place to this trip"><option value="">+ Add a place…</option>${avail.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.state)}</option>`).join("")}</select>
      ${ps.length ? routeBox(t, ps) : ""}
      ${packBox(t)}
      ${t.notes ? `<p class="muted">${esc(t.notes)}</p>` : ""}
      ${ps.some(p => p.state === "Arunachal Pradesh") ? essentialsBox() : ""}
      <div><div class="h3" style="margin-bottom:4px">Reminders</div><div class="rems">${rems.map(r=>remRow(r,false)).join("") || `<p class="muted">No reminders for this trip yet.</p>`}</div></div>
      ${plan.remForm && plan.remForm.where === t.id ? remForm("trip") : `<div class="btnrow"><button class="mini" data-act="remnew" data-trip="${t.id}">${ico("bell")} Add reminder</button></div>`}
      ${sug.length ? `<div><div class="h3" style="margin-bottom:5px">Suggested — tap to add</div><div class="sugg">${sug.map((s,i)=>`<button data-act="sugg" data-trip="${t.id}" data-i="${i}">+ ${esc(s.text)} · ${fmtD(s.date)}</button>`).join("")}</div></div>` : ""}
      <div class="btnrow">
        <button class="mini" data-act="showtrip" data-id="${t.id}">${ico("pin")} Show on map</button>
        <a class="mini" href="${gcalTrip(t)}" target="_blank" rel="noopener noreferrer">${ico("gcal")} Google Calendar</a>
        <button class="mini" data-act="edittrip" data-id="${t.id}">${ico("edit")} Edit</button>
        <button class="mini del" data-act="deltrip" data-id="${t.id}">${ico("trash")} ${plan.armDel===t.id ? "Tap again to delete" : "Delete"}</button>
      </div></div>`;
  }
  const hasPic = p => !!(shownPhotos(p).length || photosOf(p) || remotePhotosOf(p).length);
  const cover = [...ps].sort((a,b) => hasPic(b) - hasPic(a)).slice(0,3);
  return `<div class="trip">${cover.length ? `<div class="tcover" data-act="expand" data-id="${t.id}" aria-hidden="true">${cover.map(p=>thumbHTML(p)).join("")}${ps.length>3?`<span class="tmore">+${ps.length-3}</span>`:""}</div>` : ""}<div class="th" data-act="expand" data-id="${t.id}" role="button" tabindex="0" aria-expanded="${open}">
    <span class="bar" style="background:${t.color}"></span>
    <div><b>${esc(t.name)}</b><br><span>${fmtD(t.start)} – ${fmtD(t.end, true)} · ${n} day${n>1?"s":""} · ${ps.length} place${ps.length!==1?"s":""}</span></div>
    <span class="tstat ${st.cls}">${st.txt}</span></div>${body}</div>`;
}
function calendarHTML(){
  const m = plan.month, y = m.getFullYear(), mo = m.getMonth(), td = todayISO();
  const first = new Date(y, mo, 1), startOff = (first.getDay() + 6) % 7, start = new Date(y, mo, 1 - startOff);
  const cells = [];
  for(let i=0;i<42;i++){
    const d = new Date(start); d.setDate(start.getDate()+i); const s = iso(d);
    const trs = store.trips.filter(t => t.start <= s && s <= t.end);
    const rs = store.reminders.filter(r => r.date === s);
    const band = trs[0] ? `<span class="band ${trs[0].start===s?"s":""} ${trs[0].end===s?"e":""}" style="background:${trs.length>1 ? `linear-gradient(90deg, ${trs.map(t=>t.color).join(",")})` : trs[0].color}"></span>` : "";
    cells.push(`<button class="day ${d.getMonth()!==mo?"out":""} ${s===td?"today":""} ${s===plan.selDay?"sel":""}" data-act="day" data-d="${s}" aria-label="${fmtD(s,true)}${trs.length?", "+esc(trs.map(t=>t.name).join(", ")):""}${rs.length?", "+rs.length+" reminder(s)":""}">
      <span class="n">${d.getDate()}</span><span class="dots">${rs.slice(0,3).map(r=>`<i class="${r.done?"done":""}"></i>`).join("")}</span>${band}</button>`);
    if(i >= 34 && d.getMonth() !== mo && d.getDay() === 0) break;
  }
  return `<div class="cal"><div class="calhead"><b>${MONTH_FULL[mo]} ${y}</b><button data-act="calprev" aria-label="Previous month">‹</button><button data-act="caltoday">Today</button><button data-act="calnext" aria-label="Next month">›</button></div>
    <div class="calgrid">${["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map(x=>`<span class="dow">${x}</span>`).join("")}${cells.join("")}</div></div>`;
}
function dayPanel(){
  if(!plan.selDay) return "";
  const s = plan.selDay, trs = store.trips.filter(t => t.start <= s && s <= t.end), rs = store.reminders.filter(r => r.date === s);
  return `<div class="box"><div class="h3" style="margin-bottom:6px">${parseISO(s).toLocaleDateString("en-IN",{weekday:"long",day:"numeric",month:"long",year:"numeric"})}</div>
    ${trs.map(t=>`<div class="muted" style="margin-bottom:4px"><span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${t.color};margin-right:6px"></span>${esc(t.name)} (day ${dayDiff(t.start,s)+1})</div>`).join("")}
    <div class="rems">${rs.map(r=>remRow(r,true)).join("")}</div>
    ${!trs.length && !rs.length ? `<p class="muted">Nothing planned.</p>` : ""}
    ${plan.remForm && plan.remForm.where === "day" ? remForm("day") : `<div class="btnrow" style="margin-top:8px"><button class="mini" data-act="remnew" data-day="${s}">${ico("bell")} Reminder on this day</button><button class="mini" data-act="newtrip">+ Trip from this day</button></div>`}
  </div>`;
}
function renderPlanner(){
  if(panelMode !== "planner") return;
  const d = $("detail"), keep = d.querySelector(".dscroll"), top = keep && d.dataset.pid === "planner" ? keep.scrollTop : 0;
  d.dataset.pid = "planner"; d.hidden = false;
  const due = dueReminders(14);
  const general = store.reminders.filter(r => !r.tripId).sort((a,b) => (a.date+a.time).localeCompare(b.date+b.time));
  d.innerHTML = `<div class="plain-head"><h2>Trips &amp; reminders</h2><div class="lbl" style="margin-top:4px">Plan trips, set reminders, sync to your calendar</div><button class="close" data-act="close" aria-label="Close">✕</button></div>
  <div class="dscroll"><div class="pl">
    <div><div class="h3" style="margin-bottom:6px">Due in the next 14 days</div>${due.length ? `<div class="box rems">${due.map(r=>remRow(r,true)).join("")}</div>` : `<p class="muted">Nothing due. Enjoy the calm.</p>`}</div>
    ${calendarHTML()}
    ${dayPanel()}
    <div class="btnrow" style="justify-content:space-between"><div class="h3">My trips (${store.trips.length})</div><button class="mini acc" data-act="newtrip">+ New trip</button></div>
    ${plan.editing === "new" ? tripForm(null) : ""}
    ${store.trips.length ? sortedTrips().map(tripCard).join("") : `<p class="muted">No trips yet. Create one, or open any place on the map and use “Add to trip”.</p>`}
    <div><div class="btnrow" style="justify-content:space-between;margin-bottom:6px"><div class="h3">Other reminders</div>${plan.remForm && plan.remForm.where === "general" ? "" : `<button class="mini" data-act="remnew">${ico("bell")} Add</button>`}</div>
      ${plan.remForm && plan.remForm.where === "general" ? remForm("general") : ""}
      ${general.length ? `<div class="box rems">${general.map(r=>remRow(r,false)).join("")}</div>` : `<p class="muted">Pay-commission news, festival bookings, anything not tied to a trip.</p>`}</div>
    <div class="box"><div class="h3" style="margin-bottom:6px">Get alerts on your phone</div>
      <p class="muted" style="margin-bottom:8px">This page shows reminders and the badge when you open it. For real phone alerts, tap the calendar icon on a reminder (Google Calendar) or download everything as a calendar file.</p>
      <button class="mini" data-act="ics">${ico("down")} Download calendar file (.ics)</button></div>
    <div class="box"><div class="h3" style="margin-bottom:6px">Backup &amp; restore</div>
      <p class="muted" style="margin-bottom:8px">Everything is stored only in this browser on this device. Export a backup to keep it safe or move it to another phone or laptop.</p>
      ${pendingImport ? `<p class="muted" style="margin-bottom:8px"><b>${esc(plan.importName)}</b>: ${sarr(pendingImport.store.trips).length} trips, ${sarr(pendingImport.store.reminders).length} reminders. Restoring replaces the data on this device.</p><div class="btnrow"><button class="mini acc" data-act="importok">Replace with this backup</button><button class="mini" data-act="importcancel">Cancel</button></div>`
      : pendingEnc ? importPassBox() : `<div class="btnrow"><button class="mini" data-act="export">${ico("down")} Export backup</button><label class="mini" for="impFile" style="cursor:pointer">Import backup</label><input id="impFile" type="file" accept="application/json,.json" data-import hidden></div>`}</div>
    ${lockBox()}
  </div></div>`;
  const sc = d.querySelector(".dscroll"); if(sc) sc.scrollTop = top;
}
const detailEl = $("detail");
detailEl.addEventListener("click", e => {
  const b = e.target.closest("[data-act]"); if(!b || !detailEl.contains(b)) return;
  const act = b.dataset.act, id = b.dataset.id;
  if(panelMode !== "planner" && !["close"].includes(act)) return;
  if(act !== "deltrip") plan.armDel = null;
  switch(act){
    case "close": closeDetail(); return;
    case "calprev": plan.month = new Date(plan.month.getFullYear(), plan.month.getMonth()-1, 1); break;
    case "calnext": plan.month = new Date(plan.month.getFullYear(), plan.month.getMonth()+1, 1); break;
    case "caltoday": plan.month = new Date(); plan.month.setDate(1); plan.selDay = todayISO(); break;
    case "day": plan.selDay = plan.selDay === b.dataset.d ? null : b.dataset.d; plan.remForm = null; break;
    case "newtrip": plan.editing = "new"; plan.color = TRIP_COLORS[store.trips.length % TRIP_COLORS.length]; break;
    case "tripcancel": plan.editing = null; break;
    case "edittrip": plan.editing = id; plan.color = tripById(id).color; break;
    case "swatch": plan.color = b.dataset.c; b.closest(".swatches").querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", x === b)); return;
    case "expand": plan.expanded.has(id) ? plan.expanded.delete(id) : plan.expanded.add(id); break;
    case "deltrip":
      if(plan.armDel !== id){ plan.armDel = id; break; }
      store.trips = store.trips.filter(t => t.id !== id); store.reminders = store.reminders.filter(r => r.tripId !== id);
      if(F.trip === id) F.trip = ""; plan.armDel = null; save(); toast("Trip deleted"); renderAll(); break;
    case "rmplace": { const t = tripById(b.dataset.trip); t.places = t.places.filter(x => x !== id); save(); renderAll(); break; }
    case "openplace": select(id, true); return;
    case "showtrip": showTrip(id); break;
    case "remnew": plan.remForm = { where: b.dataset.trip || (b.dataset.day ? "day" : "general"), tripId: b.dataset.trip || "", date: b.dataset.day || "" }; break;
    case "remcancel": plan.remForm = null; break;
    case "remdel": store.reminders = store.reminders.filter(r => r.id !== id); save(); renderStats(); break;
    case "remdone": { const r = store.reminders.find(x => x.id === id); r.done = b.checked; save(); renderStats(); break; }
    case "sugg": { const t = tripById(b.dataset.trip), s = suggestions(t)[+b.dataset.i]; if(s){ store.reminders.push({ id:uid(), tripId:t.id, date:s.date, time:s.time, text:s.text, done:false }); save(); renderStats(); toast("Reminder added"); } break; }
    case "ics": downloadCalendar(); return;
    case "export": exportBackup(); return;
    case "importok": applyImport(); return;
    case "importcancel": pendingImport = null; break;
    default: return;
  }
  renderPlanner();
});
