  const pts = ps.map(p => projection([p.lon,p.lat])), xs = pts.map(p=>p[0]), ys = pts.map(p=>p[1]);
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys), v = viewBox();
  const k = Math.min(12, Math.max(1, 0.7 / Math.max((x1-x0 || 1)/v.w, (y1-y0 || 1)/v.h)));
  svg.transition().duration(750).call(zoom.transform, d3.zoomIdentity.translate(v.cx, v.cy).scale(ps.length > 1 ? k : 7).translate(-(x0+x1)/2, -(y0+y1)/2));
