// ---------- your own photos ----------
let assetsNS = null, uploading = "";
const assetUrl = {};
const blobSrc = id => ID_RE.test(String(id)) && assetUrl[id] ? assetUrl[id] : "";
const userPhotosOf = p => (store.userPhotos && store.userPhotos[p.id]) || [];
function exifDate(buf){
  try {
    const v = new DataView(buf); if(v.getUint16(0) !== 0xFFD8) return null;
    let off = 2;
    while(off < v.byteLength - 10){
      const marker = v.getUint16(off), len = v.getUint16(off+2);
      if(marker === 0xFFE1 && v.getUint32(off+4) === 0x45786966){
        const t = off + 10, le = v.getUint16(t) === 0x4949;
        const g16 = o => v.getUint16(o, le), g32 = o => v.getUint32(o, le);
        const str = (o,n) => { let s = ""; for(let i=0;i<n;i++){ const c = v.getUint8(o+i); if(!c) break; s += String.fromCharCode(c); } return s; };
        const find = (ifd, tag) => { const n = g16(ifd); for(let i=0;i<n;i++){ const e = ifd + 2 + i*12; if(g16(e) === tag) return e; } return -1; };
        const ifd0 = t + g32(t+4); let s = null;
        const ex = find(ifd0, 0x8769);
        if(ex >= 0){ const e = find(t + g32(ex+8), 0x9003); if(e >= 0) s = str(t + g32(e+8), 19); }
        if(!s){ const e = find(ifd0, 0x0132); if(e >= 0) s = str(t + g32(e+8), 19); }
        const m = s && s.match(/^(\d{4}):(\d{2})/);
        return m && +m[2] >= 1 && +m[2] <= 12 ? { y:+m[1], m:+m[2] } : null;
      }
      if((marker & 0xFF00) !== 0xFF00) break;
      off += 2 + len;
    }
  } catch(e){}
  return null;
}
async function shrink(file){
  let bmp;
  try { bmp = await createImageBitmap(file); } catch(e){ throw {code:"decode"}; }
  const s = Math.min(1, 2000 / Math.max(bmp.width, bmp.height));
  const c = document.createElement("canvas"); c.width = Math.round(bmp.width*s); c.height = Math.round(bmp.height*s);
  c.getContext("2d").drawImage(bmp, 0, 0, c.width, c.height);
  return await new Promise((res, rej) => c.toBlob(b => b ? res(b) : rej({code:"decode"}), "image/jpeg", 0.86));
}
function uploadMsg(err){
  const c = err && err.code;
  return c === "decode" ? "This photo format can't be read here (HEIC?). Pick a JPEG, or set the camera to save JPEG."
    : c === "too_large" ? "That photo is too large." : c === "unsupported_type" ? "That file type isn't supported."
    : c === "quota_or_state" ? "Photo storage for this map is full." : c === "rate_limited" ? "Too many uploads at once — try again in a minute."
    : c === "store_unavailable" ? "Upload service is busy — try again." : "Upload failed.";
}
async function handleFiles(p, files){
  if(!assetsNS){ toast("Photo storage isn't available in this browser (private mode?)"); return; }
  const all = [...files], list = all.filter(f => /^image\//.test(f.type) && f.size > 0 && f.size <= 30*1024*1024).slice(0, 10);
  if(list.length < all.length) toast(list.length ? "Some files were skipped (only photos up to 30 MB, 10 at a time)" : "Only photo files up to 30 MB can be added");
  if(!list.length) return;
  let ok = 0;
  for(let i=0;i<list.length;i++){
    uploading = `Uploading ${i+1}/${list.length}…`; renderDetail(p);
    try {
      const f = list[i], dt = exifDate(await f.arrayBuffer()), blob = await shrink(f);
      const r = await assetsNS.upload(blob, { type:"image/jpeg" });
      assetUrl[r.id] = r.url;
      store.userPhotos = store.userPhotos || {};
      (store.userPhotos[p.id] = store.userPhotos[p.id] || []).unshift({ id:r.id, m: dt ? dt.m : null, y: dt ? dt.y : null, at: todayISO() });
      save(); ok++;
    } catch(err){ toast(uploadMsg(err)); }
  }
  uploading = ""; photoIdx = 0; seasonOnly = false;
  if(ok) toast(ok === 1 ? "Photo added" : `${ok} photos added`);
  renderAll(); renderDetail(p);
}
let armPhoto = null;
async function deleteUserPhoto(p, id){
  if(armPhoto !== id){ armPhoto = id; renderDetail(p); return; }
  armPhoto = null;
  try { if(assetsNS) await assetsNS.delete(id); } catch(e){ toast("Couldn't delete the photo — try again"); return; }
  store.userPhotos[p.id] = userPhotosOf(p).filter(x => x.id !== id);
  if(!store.userPhotos[p.id].length) delete store.userPhotos[p.id];
  save(); photoIdx = 0; renderAll(); renderDetail(p); toast("Photo deleted");
}

