// ---------- website storage: everything stays on this device ----------
const PhotoDB = (() => {
  let dbp = null;
  const open = () => dbp || (dbp = new Promise((res, rej) => {
    const r = indexedDB.open("bharat-bhramanam", 1);
    r.onupgradeneeded = () => r.result.createObjectStore("photos");
    r.onsuccess = () => res(r.result);
    r.onerror = () => { dbp = null; rej(r.error); };
  }));
  const tx = async (mode, fn) => {
    const db = await open();
    return new Promise((res, rej) => {
      const t = db.transaction("photos", mode), req = fn(t.objectStore("photos"));
      t.oncomplete = () => res(req ? req.result : undefined);
      t.onerror = () => rej(t.error); t.onabort = () => rej(t.error || {code:"quota_or_state"});
    });
  };
  return {
    put: (id, blob) => tx("readwrite", s => s.put(blob, id)),
    del: id => tx("readwrite", s => s.delete(id)),
    get: id => tx("readonly", s => s.get(id)),
    keys: () => tx("readonly", s => s.getAllKeys())
  };
})();
