  if(Array.isArray(d.ess)){ ARU_ESSENTIALS.length = 0; d.ess.filter(x => Array.isArray(x) && typeof x[0] === "string").forEach(x => ARU_ESSENTIALS.push([x[0].slice(0,600), typeof x[1] === "string" ? x[1] : null])); }
  for(const [k, v] of Object.entries(sobj(d.videos))) if(ID_RE.test(k) && Array.isArray(v)) VIDEOS[k] = v.filter(x => Array.isArray(x) && typeof x[0] === "string" && httpsOnly(x[1])).map(x => [x[0].slice(0,120), x[1]]);
  const info = sobj(d.info);
