// ---- payment: Razorpay Checkout; the server verifies the signature before unlocking ----
function loadRazorpay(){
  if(window.Razorpay) return Promise.resolve();
  return new Promise((res, rej) => {
    const s = document.createElement("script"); s.src = "https://checkout.razorpay.com/v1/checkout.js"; s.async = true;
    s.onload = () => window.Razorpay ? res() : rej(new Error("Payment window didn't load")); s.onerror = () => rej(new Error("Couldn't reach the payment service. Check your internet."));
    document.head.appendChild(s);
  });
}
async function startPayment(){
  if(!session){ openAccount("register", "pay"); return; }
  const btn = $("payBtn"); if(btn){ btn.disabled = true; btn.textContent = "Opening secure payment…"; }
  try {
    const token = await freshToken(); if(!token){ openAccount("login", "pay"); return; }
    const r = await fetch("/api/create-order", { method:"POST", headers:{ authorization:`Bearer ${token}` }, cache:"no-store" });
    const j = await r.json().catch(() => ({}));
    if(r.status === 409 && j.paid){ await refreshEntitlement(); openAccount("paywall"); return; }
    if(!r.ok || !/^order_[A-Za-z0-9]+$/.test(j.order_id || "") || !/^rzp_(test|live)_[A-Za-z0-9]+$/.test(j.key_id || "")) throw new Error(sstr(j.error, 160) || "Payments aren't available right now");
    await loadRazorpay();
    const rz = new window.Razorpay({
      key:j.key_id, order_id:j.order_id, amount:j.amount, currency:"INR", name:"Bharat Bhramanam", description:"All features · one-time",
      prefill:{ email:session.user.email }, notes:{ user_id:session.user.id }, theme:{ color:"#D9731A" },
      handler: resp => verifyPayment(resp),
      modal:{ ondismiss: () => { const b = $("payBtn"); if(b){ b.disabled = false; b.textContent = `Pay ${inr(PRICE)} securely`; } } }
    });
    rz.on("payment.failed", resp => acctMsg(sstr(resp && resp.error && resp.error.description, 160) || "Payment failed. No money was taken; please try again."));
    rz.open();
  } catch(err){
    acctMsg(err.message || "Payments aren't available right now");
    const b = $("payBtn"); if(b){ b.disabled = false; b.textContent = `Pay ${inr(PRICE)} securely`; }
  }
}
async function verifyPayment(resp){
  acctMsg("Confirming your payment…", true);
  const body = { razorpay_order_id:sstr(resp.razorpay_order_id, 60), razorpay_payment_id:sstr(resp.razorpay_payment_id, 60), razorpay_signature:sstr(resp.razorpay_signature, 128) };
  for(let attempt = 0; attempt < 5; attempt++){
    try {
      const r = await fetch("/api/verify-payment", { method:"POST", headers:{ authorization:`Bearer ${await freshToken()}`, "content-type":"application/json" }, body:JSON.stringify(body), cache:"no-store" });
      if(r.ok){ await refreshEntitlement(); if(ENT.paid){ closeAccount(); toast("Payment successful. All features unlocked!"); return; } }
      else if(r.status === 400){ acctMsg("We couldn't verify this payment. If money was deducted, contact support with your payment ID: " + body.razorpay_payment_id); return; }
    } catch(e){}
    await new Promise(r => setTimeout(r, 2500 * (attempt + 1)));
  }
  acctMsg("Payment received. Unlocking is taking longer than usual; reopen the site in a minute. Payment ID: " + body.razorpay_payment_id, true);
}

window.addEventListener("hashchange", () => { handleAuthHash().then(() => refreshEntitlement()); });
// ---- boot ----
const _baseConnect = connectDb;
connectDb = async function(){
  await _baseConnect();
  const c = cachedPremium(); if(c){ applyPremium(c); ENT.paid = true; }
  updateAccountUI();
  await handleAuthHash();
  await refreshEntitlement();
};

const _renderPlannerBase = renderPlanner; renderPlanner = function(){ _renderPlannerBase(); afterRender(); };
new ResizeObserver(() => layout()).observe($("stage"));
document.addEventListener("keydown", e => {
  if(e.key !== "Escape") return;
  if(!$("lb").hidden){ $("lb").hidden = true; const p = PLACES.find(x=>x.id===selectedId); if(p) renderDetail(p); }
  else if(!$("detail").hidden) closeDetail();
});
syncControls();
connectDb();
